let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");

const json = { "content-type": "application/json" };
const { transferId, fromId, toId, amount, fromBalance, toBalance, fromVersion, toVersion } = input;

const unchanged = () => [
  { id: fromId, balance: fromBalance, version: fromVersion },
  { id: toId, balance: toBalance, version: toVersion },
];

function emit(status, body, { accounts = unchanged(), committed = false, messages = [], ordering = [], failures = [], retryability = false } = {}) {
  console.log(JSON.stringify({
    http: { status, headers: json, body },
    database: { accounts, transaction: { committed } },
    messages,
    ordering,
    failures,
    retryability,
  }));
}

const replay = input.replay === true || input.previousResult || input.existingTransfer || input.idempotentReplay === true;
const prior = input.previousResult || input.existingTransfer;
const conflict =
  (input.currentFromVersion !== undefined && input.currentFromVersion !== fromVersion) ||
  (input.currentToVersion !== undefined && input.currentToVersion !== toVersion) ||
  (input.expectedFromVersion !== undefined && input.expectedFromVersion !== fromVersion) ||
  (input.expectedToVersion !== undefined && input.expectedToVersion !== toVersion);

if (replay) {
  const body = prior && typeof prior === "object" && prior.transferId
    ? prior
    : { transferId, fromBalance, toBalance, replayed: true };
  emit(200, body, {
    accounts: unchanged(),
    committed: false,
    ordering: ["idempotency-check"],
  });
} else if (conflict) {
  emit(409, { error: "version_conflict", transferId }, {
    ordering: ["version-check", "rollback"],
    failures: [{ code: "version_conflict", retryable: true }],
    retryability: true,
  });
} else if (!(amount > 0) || fromBalance < amount) {
  const code = amount > 0 ? "insufficient_funds" : "invalid_amount";
  emit(amount > 0 ? 422 : 400, { error: code, transferId }, {
    ordering: ["balance-check", "rollback"],
    failures: [{ code, retryable: false }],
  });
} else {
  const newFrom = fromBalance - amount;
  const newTo = toBalance + amount;
  emit(201, {
    transferId,
    fromBalance: newFrom,
    toBalance: newTo,
    fromVersion: fromVersion + 1,
    toVersion: toVersion + 1,
  }, {
    accounts: [
      { id: fromId, balance: newFrom, version: fromVersion + 1 },
      { id: toId, balance: newTo, version: toVersion + 1 },
    ],
    committed: true,
    messages: [{ type: "transfer.completed", transferId, fromId, toId, amount }],
    ordering: ["debit", "credit", "commit", "event"],
  });
}

